SELECT id AS id,warehouse_id AS warehouseId,sku_id AS skuId,stock_total AS stockTotal,available AS available,reserved AS reserved,sold AS sold,version AS version
FROM tc_inventory_balance WHERE tenant_id=#{tenant} AND id > #{q.after}
AND warehouse_id=#{q.filters.warehouseId}
AND sku_id=#{q.filters.skuId}
AND available <= #{q.filters.maxAvailable}
ORDER BY id LIMIT #{q.limit}


SELECT id AS id,operation_ref AS operationRef,warehouse_id AS warehouseId,sku_id AS skuId,operation_type AS operationType,available_delta AS availableDelta,reserved_delta AS reservedDelta,sold_delta AS soldDelta,total_delta AS totalDelta,reason AS reason,created_at AS occurredAt
FROM tc_inventory_ledger WHERE tenant_id=#{tenant} AND warehouse_id=#{warehouseId} AND sku_id=#{skuId} AND id>#{after}
ORDER BY id LIMIT #{limit}
